// Web adaptation: relative assets, on-demand local AI, website theme, browser downloads.
'use strict';
const $=id=>document.getElementById(id),Core=TextureCore,Codecs=TextureCodecs;
const state={assets:[],selected:new Set(),active:null,anchor:0,image:null,original:null,mask:null,selection:null,selectionFocus:false,seam:null,workBlob:null,tool:'hand',tiles:1,offset:false,grid:false,inspect:false,inspectX:0,inspectY:0,zoom:1,panX:0,panY:0,pointer:null,space:false,busy:false,cancel:false,worker:null,copyTarget:'original',ratio:true,exportScale:1,exportMode:'native',historyLimit:30,historySeq:0,directory:null,pinned:false,thumbs:new Map(),thumbQueue:[],thumbRunning:0,session:crypto.randomUUID(),memory:new Map()};
const currentCanvas=document.createElement('canvas'),originalCanvas=document.createElement('canvas'),maskCanvas=document.createElement('canvas');
const desktop=null;
const aiBase=new URL('./ai/',location.href).href;
let dbPromise,toastTimer,renderQueued=false,importSeq=0;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500)}
function status(message){$('status').textContent=message}
function delay(){return new Promise(r=>setTimeout(r,0))}
function fail(e){console.error(e);if(e?.name!=='AbortError')toast(e.message||String(e))}
function bind(id,event,fn){$(id).addEventListener(event,e=>{try{Promise.resolve(fn(e)).catch(fail)}catch(err){fail(err)}})}
function isTextInput(target){return target?.matches('input,textarea,select,[contenteditable="true"]')}
function setCanvas(canvas,im){canvas.width=im.width;canvas.height=im.height;canvas.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(im.data),im.width,im.height),0,0)}
function canvasBlob(canvas,type='image/png',quality){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('图片编码失败。')),type,quality))}
function packMask(a){if(!a)return new Uint32Array();let runs=[],value=a[0],len=0;for(let i=0;i<a.length;i++){if(a[i]===value&&len<0xffffff)len++;else{runs.push(((value<<24)|len)>>>0);value=a[i];len=1}}if(len)runs.push(((value<<24)|len)>>>0);return new Uint32Array(runs)}
function unpackMask(runs,n){let a=new Uint8Array(n),p=0;for(let r of runs||[]){let len=r&0xffffff;a.fill(r>>>24,p,p+len);p+=len}return a}
function openDB(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{let req=indexedDB.open('SeamlessStudioLocalCache',1);req.onupgradeneeded=()=>req.result.createObjectStore('edits',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return dbPromise}
async function cacheGet(asset){if(!asset.hasEdit)return null;try{let db=await openDB();return await new Promise((res,rej)=>{let req=db.transaction('edits').objectStore('edits').get(state.session+'/'+asset.id);req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)})}catch(e){return state.memory.get(asset.id)||null}}
async function cachePut(asset,record){record={...record,id:state.session+'/'+asset.id,time:Date.now()};try{let db=await openDB();await new Promise((res,rej)=>{let tx=db.transaction('edits','readwrite');tx.objectStore('edits').put(record);tx.oncomplete=res;tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error)})}catch(e){let used=[...state.memory.values()].reduce((n,r)=>n+r.blob.size,0);if(used+record.blob.size>64*1024*1024)throw Error('本地缓存不可用，内存缓存已满。请先导出已有结果，再刷新网页。');state.memory.set(asset.id,record)}asset.hasEdit=true}
async function cacheDelete(asset){state.memory.delete(asset.id);try{let db=await openDB();db.transaction('edits','readwrite').objectStore('edits').delete(state.session+'/'+asset.id)}catch(e){}}
async function pruneOldCache(){try{let db=await openDB(),tx=db.transaction('edits','readwrite'),store=tx.objectStore('edits'),req=store.openCursor(),deadline=Date.now()-7*86400000;req.onsuccess=()=>{let c=req.result;if(c){if(c.value.time<deadline)c.delete();c.continue()}}}catch(e){}}
async function api(route,body,headers={}){const r=await fetch(route,{method:'POST',headers:{'X-Studio-Token':desktop.token,...headers},body});const data=await r.json();if(!r.ok)throw Error(data.error||'桌面服务未响应。');return data}
async function decode(file){
 const ext=(file.name||'').split('.').pop().toLowerCase();
 if(['tga','tif','tiff','bmp'].includes(ext)){let buffer=await file.arrayBuffer(),im=ext==='tga'?Codecs.decodeTGA(buffer):ext==='bmp'?Codecs.decodeBMP(buffer):await Codecs.decodeTIFF(buffer);if(im)return im}
 if(ext==='svg'||file.type==='image/svg+xml'){const url=URL.createObjectURL(new Blob([file],{type:'image/svg+xml'}));try{let img=new Image();img.src=url;await img.decode();Codecs.checkSize(img.naturalWidth,img.naturalHeight);let c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;let ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0);return {width:c.width,height:c.height,data:ctx.getImageData(0,0,c.width,c.height).data}}finally{URL.revokeObjectURL(url)}}
 let bitmap;try{bitmap=await createImageBitmap(file,{imageOrientation:'from-image'})}catch(e){throw Error('无法读取 '+(file.name||'图片')+'。请检查格式；PSD、EXR、DDS、HEIC 暂不支持。')}
 try{Codecs.checkSize(bitmap.width,bitmap.height);let c=document.createElement('canvas');c.width=bitmap.width;c.height=bitmap.height;let ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0);return {width:c.width,height:c.height,data:ctx.getImageData(0,0,c.width,c.height).data}}finally{bitmap.close()}
}
function supported(file){return /\.(png|jpe?g|webp|tiff?|tga|bmp|gif|avif|svg)$/i.test(file.name)||file.type.startsWith('image/')}
async function addFiles(files){
 if(state.busy)return toast('请等待当前操作完成。');const list=Array.from(files).filter(supported);if(!list.length)return toast('没有可导入的图片。支持 PNG / JPEG / WebP / TIFF / TGA / BMP / GIF / AVIF / SVG。');
 let first=state.assets.length;for(let f of list)state.assets.push({id:++importSeq,file:f,name:f.name||('粘贴图片-'+importSeq+'.png'),hasEdit:false,history:[],redo:[],error:null,dimensions:null});
 state.selected=new Set(state.assets.slice(first).map(a=>a.id));state.anchor=first;renderLibrary();status('已加入 '+list.length.toLocaleString()+' 张图片 · 缩略图按需加载');
 if(!state.active)await activate(state.assets[first]);else toast('已加入 '+list.length.toLocaleString()+' 张图片');
}
function thumbKey(a){return a.id+':'+(a.revision||0)}
function queueThumbnail(a){let key=thumbKey(a);if(state.thumbs.has(key)||state.thumbQueue.some(x=>x.key===key))return;state.thumbQueue.push({asset:a,key});pumpThumbnails()}
async function pumpThumbnails(){
 if(state.thumbRunning>=2||!state.thumbQueue.length)return;let job=state.thumbQueue.shift();state.thumbRunning++;state.thumbs.set(job.key,{pending:true});pumpThumbnails();
 try{let record=job.asset.hasEdit?await cacheGet(job.asset):null;let im=await decode(record?new File([record.blob],'thumb.png'):job.asset.file);job.asset.dimensions=[im.width,im.height];let c=document.createElement('canvas');let scale=Math.min(112/im.width,68/im.height,1);c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));let tmp=document.createElement('canvas');setCanvas(tmp,im);c.getContext('2d').drawImage(tmp,0,0,c.width,c.height);let b=await canvasBlob(c);tmp.width=tmp.height=1;let url=URL.createObjectURL(b);state.thumbs.set(job.key,{url});
  while(state.thumbs.size>120){let entry=[...state.thumbs.entries()].find(([k,v])=>!v.pending&&k!==job.key);if(!entry)break;if(entry[1].url)URL.revokeObjectURL(entry[1].url);state.thumbs.delete(entry[0])}
  let el=$('assetItems').querySelector('[data-id="'+job.asset.id+'"] .asset-thumb');if(el&&thumbKey(job.asset)===job.key){let old=el.querySelector('img');if(old)old.remove();let img=document.createElement('img');img.src=url;img.alt='';el.prepend(img)}
 }catch(e){job.asset.error=e.message;state.thumbs.set(job.key,{error:true})}finally{state.thumbRunning--;pumpThumbnails()}
}
function renderLibrary(){
 const list=$('assetList'),count=state.assets.length,rowH=108,rows=Math.ceil(count/2),start=Math.max(0,Math.floor(list.scrollTop/rowH)-1),end=Math.min(rows,Math.ceil((list.scrollTop+list.clientHeight)/rowH)+2);
 $('assetCount').textContent=count.toLocaleString();$('selectedCount').textContent=state.selected.size?'已选 '+state.selected.size.toLocaleString()+' 张':'未选择素材';$('assetSpacer').style.height=rows*rowH+'px';$('libraryEmpty').hidden=count>0;
 const frag=document.createDocumentFragment();const visible=new Set();for(let i=start*2;i<Math.min(count,end*2);i++){
  let a=state.assets[i],el=document.createElement('div');visible.add(a.id);el.className='asset'+(state.selected.has(a.id)?' selected':'')+(state.active?.id===a.id?' current':'');el.dataset.id=a.id;el.dataset.index=i;el.style.top=Math.floor(i/2)*rowH+'px';el.style.left=(i%2?'calc(50% + 2px)':'4px');el.title=a.name+(a.error?'\n'+a.error:'');
  let thumb=document.createElement('div');thumb.className='asset-thumb';thumb.draggable=true;thumb.dataset.dragId=a.id;let cached=state.thumbs.get(thumbKey(a));if(cached?.url){let img=document.createElement('img');img.src=cached.url;img.alt='';thumb.append(img)}else{let t=document.createElement('span');t.className='eyebrow';t.textContent=a.error?'无法预览':'TEXTURE';thumb.append(t)}
  let handle=document.createElement('span');handle.className='drag-handle';handle.draggable=true;handle.textContent='拖到工作台 ↗';handle.dataset.dragId=a.id;thumb.append(handle);el.append(thumb);let label=document.createElement('span');label.className='asset-name';label.textContent=a.name;el.append(label);if(a.hasEdit){let dot=document.createElement('span');dot.className='asset-state';el.append(dot)}frag.append(el);
 }
 $('assetItems').replaceChildren(frag);state.thumbQueue=state.thumbQueue.filter(x=>visible.has(x.asset.id));for(let id of visible){let a=state.assets.find(x=>x.id===id);queueThumbnail(a)}
 $('batchSeamBtn').disabled=!state.selected.size;$('batchExportBtn').disabled=!state.selected.size;$('removeBtn').disabled=!state.selected.size;
}
async function persistActive(){if(!state.active||!state.image)return;await cachePut(state.active,{blob:state.workBlob,mask:packMask(state.mask),selection:state.selection,seam:state.seam});}
async function activate(asset){
 if(state.busy||!asset||asset.id===state.active?.id)return;
 await withBusy('载入贴图',async()=>{
  await persistActive();let record=await cacheGet(asset);const original=await decode(asset.file);const im=record?await decode(new File([record.blob],'working.png')):Core.copy(original);
  state.active=asset;state.original=original;state.image=im;state.mask=record?unpackMask(record.mask,im.width*im.height):new Uint8Array(im.width*im.height);state.selection=record?.selection||null;state.seam=record?.seam||null;
  setCanvas(originalCanvas,original);setCanvas(currentCanvas,im);state.workBlob=record?.blob||await canvasBlob(currentCanvas);state.maskDirty=true;state.offset=false;state.inspect=false;state.inspectX=state.inspectY=0;state.tiles=1;asset.dimensions=[original.width,original.height];$('fileName').value=asset.name.replace(/\.[^.]+$/,'')+'_seamless';resetOutput();fit();updateUI();renderLibrary();
 });
}
function snapshot(){return {blob:state.workBlob,mask:packMask(state.mask),selection:state.selection?{...state.selection}:null,seam:state.seam,seq:++state.historySeq}}
function pushHistory(frame){if(!frame||!state.active)return;state.active.history.push(frame);state.active.redo=[];trimHistory();updateUI()}
function trimHistory(){let all=[];for(let a of state.assets)for(let kind of ['history','redo'])for(let f of a[kind])all.push({a,kind,f,size:f.blob.size+f.mask.byteLength});let total=all.reduce((n,e)=>n+e.size,0);all.sort((a,b)=>a.f.seq-b.f.seq);for(let e of all){if(total<=128*1024*1024&&e.a[e.kind].length<=state.historyLimit)continue;e.a[e.kind]=e.a[e.kind].filter(x=>x!==e.f);total-=e.size}}
async function historyMove(redo){if(!state.image||state.busy)return;let from=redo?state.active.redo:state.active.history,to=redo?state.active.history:state.active.redo;if(!from.length)return;await withBusy(redo?'重做':'撤销',async()=>{let target=from[from.length-1],im=await decode(new File([target.blob],'history.png'));let current=snapshot();from.pop();to.push(current);state.image=im;state.mask=unpackMask(target.mask,im.width*im.height);state.selection=target.selection;state.seam=target.seam;state.workBlob=target.blob;setCanvas(currentCanvas,im);state.maskDirty=true;state.active.revision=(state.active.revision||0)+1;await persistActive();resetOutput();fit();updateUI();renderLibrary()})}
async function replaceImage(im,frame,seam=null){pushHistory(frame);state.image=im;state.mask=new Uint8Array(im.width*im.height);state.maskDirty=true;state.seam=seam;setCanvas(currentCanvas,im);state.workBlob=await canvasBlob(currentCanvas);state.active.revision=(state.active.revision||0)+1;await persistActive();updateUI();renderLibrary();scheduleDraw()}
function progress(v,message){$('progressBar').style.width=Math.round(Math.max(0,Math.min(1,v))*100)+'%';if(message)$('busyText').textContent=message}
async function withBusy(title,fn){if(state.busy)return;state.busy=true;state.cancel=false;$('busyTitle').textContent=title;$('busyText').textContent='准备处理中…';progress(0);$('busyOverlay').hidden=false;try{await delay();return await fn()}catch(e){if(e.name==='AbortError')toast('操作已取消，已完成的批量结果保留。');else throw e}finally{state.busy=false;state.jobWorker?.terminate();state.jobWorker=null;state.worker=null;state.batchProgress=null;$('busyOverlay').hidden=true;updateUI()}}
function checkCancel(){if(state.cancel)throw new DOMException('已取消','AbortError')}
function runWorker(op,im,opts={},mask=null){
 checkCancel();return new Promise((resolve,reject)=>{
  let worker=state.jobWorker||new Worker(new URL('./process-worker.js',location.href));state.jobWorker=worker;state.worker=worker;state.rejectWorker=reject;
  worker.onmessage=e=>{if(e.data.progress!==undefined){if(state.batchProgress){let b=state.batchProgress;progress((b.index+e.data.progress)/b.total,(b.index+1)+' / '+b.total+' · '+b.name+' · '+(e.data.text||''))}else progress(e.data.progress,e.data.text);return}state.worker=null;state.rejectWorker=null;if(e.data.error)reject(Error(e.data.error));else resolve(e.data.result)};
  worker.onerror=e=>{worker.terminate();state.jobWorker=null;state.worker=null;state.rejectWorker=null;reject(Error(e.message||'图像处理失败。'))};worker.postMessage({op,image:im,options:opts,mask});
 })
}
function squareSource(im,selection=null){if(im.width===im.height)return im;if(selection&&selection.w===selection.h&&selection.w>0)return Core.rect(im,selection);let n=Math.min(im.width,im.height);return Core.rect(im,{x:Math.floor((im.width-n)/2),y:Math.floor((im.height-n)/2),w:n,h:n})}
function resetOutput(){if(!state.image)return;let n=Math.min(state.image.width,state.image.height);$('outW').value=$('outH').value=n;state.exportScale=1;state.exportMode='native'}
function seamOptions(auto=false){return {method:auto?'match':$('method').value,axes:auto?'both':$('axes').value,band:auto ? 0.2 : Number($('band').value)/100,feather:auto ? 0.35 : Number($('feather').value)/100}}
async function processSeam(auto=false){if(!state.image)return toast('请先导入图片。');const scope=auto?'all':$('scope').value;if(scope==='selection'&&!state.selection)return toast('请先在工作台框选一个范围。');if(scope==='mask'&&!state.mask.some(v=>v))return toast('请先用笔刷涂抹处理区域。');await withBusy(auto?'智能生成无缝贴图':'处理指定范围',async()=>{const frame=snapshot(),options=seamOptions(auto);let source=scope==='selection'?Core.rect(state.image,state.selection):scope==='all'?squareSource(state.image,state.selection):state.image;let result=await runWorker('seam',source,options);checkCancel();let seam=scope==='all'?options.axes:null;if(scope==='selection'){let r=state.selection,base=Core.copy(state.image);for(let y=0;y<r.h;y++)base.data.set(result.data.subarray(y*r.w*4,(y+1)*r.w*4),((r.y+y)*base.width+r.x)*4);result=base}else if(scope==='mask')result=Core.applyMasked(state.image,result,state.mask);if(scope==='all')state.selection=null;let changedSize=result.width!==state.image.width||result.height!==state.image.height;await replaceImage(result,frame,seam);if(changedSize){resetOutput();fit()}status(scope==='all'?'无缝处理完成 · '+(seam==='both'?'四边已对齐':'指定方向已对齐'):'局部处理完成 · 全图边缘不保证连续');toast('处理完成，可切换 2×2 / 3×3 检查平铺效果。')})}
async function crop(){if(!state.image)return;if(!state.selection)return toast('请先框选裁切范围。');await withBusy('裁切贴图',async()=>{let frame=snapshot(),im=Core.rect(state.image,state.selection);state.selection=null;state.offset=false;await replaceImage(im,frame,null);resetOutput();fit();updateUI();status('裁切完成 · 原始文件仍保留，可撤销')})}
let aiWorker=null,aiIdleTimer;
function releaseAI(){clearTimeout(aiIdleTimer);aiWorker?.terminate();aiWorker=null}
function runAI(im,mask){
 checkCancel();clearTimeout(aiIdleTimer);
 return new Promise((resolve,reject)=>{
  if(!aiWorker)aiWorker=new Worker(new URL('worker.js',aiBase));let worker=aiWorker;state.worker=worker;
  const finish=()=>{state.worker=null;state.rejectWorker=null;aiIdleTimer=setTimeout(releaseAI,120000)};
  state.rejectWorker=e=>{releaseAI();finish();reject(e)};
  worker.onmessage=e=>{if(e.data.progress!==undefined){progress(e.data.progress,e.data.text);return}finish();if(e.data.error){releaseAI();reject(Error('AI 修复失败：'+e.data.error+'。可改用「纹理修复」再试。'))}else resolve(e.data.result)};
  worker.onerror=e=>{releaseAI();finish();reject(Error('AI 修复未完成：'+(e.message||'运行内存不足')+'。可改用「纹理修复」。'))};
  worker.postMessage({image:im,mask,options:{lock:!!state.seam,axes:state.seam},base:aiBase});
 });
}
async function heal(){if(!state.image)return;if(!state.mask.some(v=>v))return toast('先用笔刷涂抹需要修正的区域。');const useAI=$('healMethod').value==='ai';await withBusy(useAI?'AI 重建涂抹区域':'纹理精细修复',async()=>{let frame=snapshot(),result=useAI?await runAI(state.image,state.mask):await runWorker('heal',state.image,{lock:!!state.seam,axes:state.seam},state.mask);checkCancel();if(useAI&&state.seam)Core.lockEdges(result,state.seam);await replaceImage(result,frame,state.seam);status((useAI?'AI 结构修复':'纹理修复')+'完成 · Ctrl+Z 可对比修复前后')})}
function clearMask(){if(state.busy||!state.mask||!state.mask.some(v=>v))return;pushHistory(snapshot());state.mask.fill(0);state.maskDirty=true;scheduleDraw();status('已清除涂抹，可撤销')}
function clearSelection(){if(state.busy||!state.selection)return;pushHistory(snapshot());state.selection=null;updateUI();scheduleDraw()}
function updateUI(){
 const im=state.image,has=!!im;$('welcome').hidden=has;$('stageHint').hidden=!has;
 $('documentName').textContent=state.active?.name||'工作台';$('undoBtn').disabled=!state.active?.history.length||state.busy;$('redoBtn').disabled=!state.active?.redo.length||state.busy;
 $('eraserTool').classList.toggle('active',state.tool==='brush'&&$('eraser').checked);for(let id of ['autoBtn','applySeamBtn','healBtn','exportBtn','quickExportBtn','downloadOriginalBtn','copyOriginalBtn','copyResultBtn','cropBtn','selectionMaskBtn'])$(id).disabled=!has;
 let r=state.selection;for(let [id,key] of [['selX','x'],['selY','y'],['selW','w'],['selH','h']])$(id).value=r?.[key]??(key==='w'?im?.width||0:key==='h'?im?.height||0:0);
 $('seamBadge').textContent=state.seam==='both'?'四边对齐':state.seam?'单向对齐':'待处理';$('seamBadge').classList.toggle('good',!!state.seam);
 $('pixelInfo').textContent=im?im.width+' × '+im.height+' px · RGBA':'';
 $('originalMeta').textContent=state.original?state.original.width+' × '+state.original.height+' · 原始文件':'原始文件完整保留';$('resultMeta').textContent=im?im.width+' × '+im.height+' · '+(state.seam==='both'?'四周连续':state.seam?'单向连续':'当前结果'):'等待导入';
 $('historyInfo').textContent=state.active?'撤销 '+state.active.history.length+' 步 · Ctrl+Shift+Z 重做':'Ctrl+Z 撤销 · Ctrl+Shift+Z 重做';
 $('inspectBtn').classList.toggle('active',state.inspect);$('stageHint').textContent=state.inspect?'固定四方巡检 · 按住左键，上下左右拖动循环纹理':state.tool==='brush'?'涂抹需要修正的区域，再点击「智能修复」':state.tool==='crop'?'拖动框选裁切范围，按 Enter 确认':state.tool==='hand'?'拖动平移 · 滚轮缩放':'拖动定义贴图范围 · 滚轮缩放 · 空格平移';
 document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===state.tool));document.querySelectorAll('[data-tiles]').forEach(b=>b.classList.toggle('active',Number(b.dataset.tiles)===state.tiles));$('offsetBtn').classList.toggle('active',state.offset);$('gridBtn').classList.toggle('active',state.grid);$('stage').style.cursor=state.tool==='hand'||state.space?'grab':state.tool==='brush'?'none':'crosshair';$('zoomValue').textContent=Math.round(state.zoom*100)+'%';scheduleDraw();
}
function checker(ctx,x,y,w,h){let css=getComputedStyle(document.documentElement),c=document.createElement('canvas');c.width=c.height=16;let g=c.getContext('2d');g.fillStyle=css.getPropertyValue('--checker-a');g.fillRect(0,0,16,16);g.fillStyle=css.getPropertyValue('--checker-b');g.fillRect(0,0,8,8);g.fillRect(8,8,8,8);ctx.fillStyle=ctx.createPattern(c,'repeat');ctx.fillRect(x,y,w,h)}
