async function exportCurrent(){if(!state.image)return;await withBusy('导出贴图',async()=>{let w=Number($('outW').value),h=Number($('outH').value);if(!Number.isInteger(w)||!Number.isInteger(h))throw Error('输出宽高必须是整数。');Codecs.checkSize(w,h);if(w!==h)throw Error('目前仅支持正方形输出，请设置相同的宽高。');let im=squareSource(state.image,state.selection);if(w!==im.width||h!==im.height)im=await runWorker('resize',im,{width:w,height:h,method:$('resample').value});checkCancel();if(state.seam)Core.lockEdges(im,state.seam);let format=$('format').value,blob=await exportImage(im,format),name=safeName($('fileName').value.replace(/\.(png|jpe?g|webp|tiff?|tga|bmp)$/i,''))+'.'+extension(format);let path=await writeBlob(blob,name);status('已保存：'+path);toast('已导出 '+name)})}
async function downloadOriginal(){if(!state.active)return;let path=await writeBlob(state.active.file,safeName(state.active.name));status('原始文件已保存：'+path);toast('已保存未经处理的原始文件')}
async function batchProcess(exportOnly=false){
 if(!state.selected.size)return;let selected=state.assets.filter(a=>state.selected.has(a.id));
 await withBusy(exportOnly?'批量导出 '+selected.length+' 张':'批量无缝处理 '+selected.length+' 张',async()=>{
  await persistActive();let done=0,errors=[];let scale=state.exportScale||1,format=$('format').value,opts=seamOptions(false);const archive=exportOnly&&!state.directory?new TextureArchive():null;
  for(let asset of selected){checkCancel();state.batchProgress={index:done+errors.length,total:selected.length,name:asset.name};progress((done+errors.length)/selected.length,(done+1)+' / '+selected.length+' · '+asset.name);try{
   let record=await cacheGet(asset),im=record?await decode(new File([record.blob],'result.png')):await decode(asset.file),seam=record?.seam;
   if(!exportOnly){let originalBlob=record?.blob;if(!originalBlob){let c=document.createElement('canvas');setCanvas(c,im);originalBlob=await canvasBlob(c);c.width=c.height=1}let previous={blob:originalBlob,mask:record?.mask||new Uint32Array(),selection:record?.selection||null,seam:record?.seam||null,seq:++state.historySeq};im=squareSource(im,record?.selection);im=await runWorker('seam',im,opts);checkCancel();let c=document.createElement('canvas');setCanvas(c,im);let blob=await canvasBlob(c);c.width=c.height=1;await cachePut(asset,{blob,mask:new Uint32Array(),selection:null,seam:opts.axes});asset.history.push(previous);asset.redo=[];if(done%50===0||previous.blob.size>1048576)trimHistory();asset.revision=(asset.revision||0)+1;if(asset.id===state.active?.id){state.image=im;state.workBlob=blob;state.mask=new Uint8Array(im.width*im.height);state.maskDirty=true;state.selection=null;state.seam=opts.axes;setCanvas(currentCanvas,im);resetOutput();fit();updateUI()}}
   else{im=squareSource(im,record?.selection);let w=state.exportMode==='custom'?Number($('outW').value):Math.max(1,Math.round(im.width*scale)),h=w;Codecs.checkSize(w,h);if(w!==im.width||h!==im.height)im=await runWorker('resize',im,{width:w,height:h,method:$('resample').value});if(seam)Core.lockEdges(im,seam);let b=await exportImage(im,format),name=safeName(asset.name.replace(/\.[^.]+$/,''))+'_seamless.'+extension(format);if(archive)await archive.add(name,b);else await writeBlob(b,name)}done++;
  }catch(e){if(e.name==='AbortError')throw e;errors.push(asset.name+'：'+e.message)}if(done%10===0)await delay();
  }if(archive&&done){if(errors.length){try{await archive.add('批量处理错误报告.txt',new Blob([errors.join('\r\n')],{type:'text/plain;charset=utf-8'}))}catch(reportError){console.warn('下载包已满，错误详情见状态提示',reportError)}}await writeBlob(archive.finish(),'四方连续贴图_批量.zip')}trimHistory();renderLibrary();let message=(exportOnly?'批量导出':'批量处理')+'完成：成功 '+done+'，失败 '+errors.length;status(message);toast(message);if(errors.length){console.warn(errors);let report=new Blob([errors.join('\r\n')],{type:'text/plain;charset=utf-8'});if(state.directory)await writeBlob(report,'批量处理错误报告.txt');else toast(message+'；首个错误：'+errors[0])}
 })
}
async function copyPreview(target=state.copyTarget){if(!state.image)return;let blob=await canvasBlob(target==='original'?originalCanvas:currentCanvas);if(!navigator.clipboard?.write)throw Error('此环境无法写入图片剪贴板，请使用桌面版或 Edge / Chrome。');await navigator.clipboard.write([new ClipboardItem({'image/png':blob})]);toast('已复制'+(target==='original'?'原始图':'生成图')+'，可粘贴到其他软件')}
