bind('demoBtn','click',async()=>{let w=640,h=480,im=Core.image(w,h),seed=12345;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};let grid=Array.from({length:33*33},()=>random());const noise=(x,y,scale)=>{x=x/scale%31;y=y/scale%31;let ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy;fx=fx*fx*(3-2*fx);fy=fy*fy*(3-2*fy);return (grid[iy*33+ix]*(1-fx)+grid[iy*33+ix+1]*fx)*(1-fy)+(grid[(iy+1)*33+ix]*(1-fx)+grid[(iy+1)*33+ix+1]*fx)*fy};for(let y=0;y<h;y++)for(let x=0;x<w;x++){let n=noise(x,y,90)*.42+noise(x,y,25)*.3+noise(x,y,8)*.18+random()*.1,vein=Math.pow(Math.max(0,1-Math.abs(Math.sin(x*.014+y*.007+noise(x,y,60)*8))*9),2),v=85+n*92-vein*28,i=(y*w+x)*4;im.data[i]=v*.96+8;im.data[i+1]=v*1.03+3;im.data[i+2]=v*1.04;im.data[i+3]=255}let c=document.createElement('canvas');setCanvas(c,im);await addFiles([new File([await canvasBlob(c)],'石材样例.png',{type:'image/png'})])});


